{
  "title": "Đà Lạt quanh một góc phố",
  "summary": "Một ngày thong thả quanh khu vực trung tâm, từ sáng muộn đến tối, ăn uống ngay cạnh những điểm dừng chân.",
  "stops": [
    {
      "poi_id": "p179",
      "kind": "meal",
      "must_do_id": null,
      "note": "Bữa trưa nhẹ nhàng, ngay khu vực trung tâm, hợp với người thích khởi động muộn.",
      "must_do_id": null
    },
    {
      "poi_id": "p131",
      "kind": "activity",
      "must_do_id": null,
      "note": "Đi dạo quanh hồ cho chậm rãi, không cần đi xa vẫn thấy Đà Lạt hiền lành.",
      "must_do_id": null
    },
    {
      "poi_id": "p136",
      "kind": "activity",
      "must_do_id": null,
      "note": "Nhà ga cổ gần hồ, ghé xem kiến trúc và chụp vài tấm ảnh cho có chất Đà Lạt.",
      "must_do_id": null
    },
    {
      "poi_id": "p157",
      "kind": "meal",
      "must_do_id": null,
      "note": "Tối ngồi xuống ăn nem nướng đúng kiểu, ngon quá, khỏi cần đi đâu xa.",
      "must_do_id": null
    },
    {
      "poi_id": "p144",
      "kind": "activity",
      "must_do_id": null,
      "note": "Sau bữa tối, ghé khu phức hợp gần đó cho hợp với cú đêm, không phải chạy xe lòng vòng.",
      "must_do_id": null
    }
  ]
}
```

